CREATE TYPE public.app_role AS ENUM ('admin','vendor','buyer');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT, INSERT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own roles" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY "Create own buyer role" ON public.user_roles FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND role = 'buyer');
CREATE TABLE public.vendors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, business_name text NOT NULL, slug text NOT NULL UNIQUE, category text NOT NULL, description text NOT NULL DEFAULT '', location text NOT NULL, phone text NOT NULL DEFAULT '', whatsapp text NOT NULL DEFAULT '', verified_status boolean NOT NULL DEFAULT false, image_url text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.vendors TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.vendors TO authenticated;
GRANT ALL ON public.vendors TO service_role;
ALTER TABLE public.vendors ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Anyone reads vendors" ON public.vendors FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Owners create vendors" ON public.vendors FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND verified_status = false);
CREATE POLICY "Owners update vendors" ON public.vendors FOR UPDATE TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid() AND verified_status = false);
CREATE POLICY "Owners delete vendors" ON public.vendors FOR DELETE TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vendor_id uuid NOT NULL REFERENCES public.vendors(id) ON DELETE CASCADE, title text NOT NULL, price numeric(12,2) NOT NULL DEFAULT 0, description text NOT NULL DEFAULT '', image_url text, in_stock boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.products TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.products TO authenticated;
GRANT ALL ON public.products TO service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Anyone reads products" ON public.products FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Owners create products" ON public.products FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM public.vendors v WHERE v.id = vendor_id AND v.user_id = auth.uid()));
CREATE POLICY "Owners update products" ON public.products FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.vendors v WHERE v.id = vendor_id AND v.user_id = auth.uid())) WITH CHECK (EXISTS (SELECT 1 FROM public.vendors v WHERE v.id = vendor_id AND v.user_id = auth.uid()));
CREATE POLICY "Owners delete products" ON public.products FOR DELETE TO authenticated USING (EXISTS (SELECT 1 FROM public.vendors v WHERE v.id = vendor_id AND v.user_id = auth.uid()));
CREATE TABLE public.reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vendor_id uuid NOT NULL REFERENCES public.vendors(id) ON DELETE CASCADE, user_id uuid NOT NULL, rating integer NOT NULL CHECK (rating BETWEEN 1 AND 5), comment text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(vendor_id,user_id));
GRANT SELECT ON public.reviews TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.reviews TO authenticated;
GRANT ALL ON public.reviews TO service_role;
ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Anyone reads reviews" ON public.reviews FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Buyers create reviews" ON public.reviews FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid());
CREATE POLICY "Authors edit reviews" ON public.reviews FOR UPDATE TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE POLICY "Authors delete reviews" ON public.reviews FOR DELETE TO authenticated USING (user_id = auth.uid());
CREATE INDEX vendors_category_idx ON public.vendors(category);
CREATE INDEX products_vendor_idx ON public.products(vendor_id);
CREATE INDEX reviews_vendor_idx ON public.reviews(vendor_id);